import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 await call('Page.navigate',{url:'http://127.0.0.1:3000'});
 await new Promise(r=>setTimeout(r,400));
 const result=await call('Runtime.evaluate',{awaitPromise:true,returnByValue:true,expression:`(async()=>{
 const {ToyRoomBattle}=await import('/src/js/toy-room/ToyRoomBattle.js');
 const {ARENA_TUNING,ArenaPlayerController}=await import('/src/js/toy-room/ArenaPlayerController.js');
 const {ARENA_ENEMIES}=await import('/src/js/toy-room/ArenaEnemies.js');
 const {updateArenaPlayerAnimation,sampleArenaPlayerAnimation}=await import('/src/js/toy-room/ArenaPlayerAnimation.js');
 const {ArenaPlayerRenderer}=await import('/src/js/toy-room/ArenaPlayerRenderer.js');
 const room={player:{x:650,facing:'right',animTime:0},keysDown:{ArrowLeft:true},gamepadState:{},touchState:{},tutorial:{},furniture:[],clearInput(){},story:{state:{},attack(){return true;}}};
 const b=new ToyRoomBattle(room,{loadAssets:false});b.tuning=ARENA_TUNING;b.playerController=new ArenaPlayerController();b.presentation={enemies:ARENA_ENEMIES,updateAnimation:dt=>updateArenaPlayerAnimation(b.state,room.player,dt)};b.activate();b.state.transition=null;room.keysDown={ArrowLeft:true};room.player.x=650;b.state.enemy.x=1000;b.state.enemy.state='IDLE';b.state.enemy.elapsed=-1000;
 const renderer=new ArenaPlayerRenderer();await renderer.load();const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=340;document.body.replaceChildren(canvas);document.body.style='margin:0;background:#292333';const ctx=canvas.getContext('2d');ctx.fillStyle='#44354c';ctx.fillRect(0,0,1080,340);const states=[];
 function draw(index,label){const sample=sampleArenaPlayerAnimation(b.state,room.player);states.push({label,x:room.player.x,pose:sample.pose,moving:room.player.isMoving,guard:b.state.guarding});ctx.save();ctx.translate(index*360+180-room.player.x,0);renderer.render(ctx,room,b.state,310);ctx.restore();ctx.fillStyle='white';ctx.font='16px sans-serif';ctx.fillText(label,index*360+28,28);}
 b.update(7);draw(0,'1. Caminhando para trás');const before=room.player.x;
 b.state.enemy.x=before+b.getEnemyCollisionDistance('train')+4;b.state.enemy.facing=-1;b.beginEnemyAttack('Front Charge');b.update(12);draw(1,'2. Base firme em defesa');
 if(room.player.x!==before)throw Error('Base deslizou');while(b.state.enemy.elapsed<72)b.update(1);b.update(7);draw(2,'3. Caminhando novamente');
 if(states.map(s=>s.pose).join(',')!=='run,guard,run')throw Error(JSON.stringify(states));return states;
})()`});
 if(result.result?.exceptionDetails)throw Error(JSON.stringify(result.result.exceptionDetails));
 assert.ok(result.result?.result?.value);console.log(JSON.stringify(result.result.result.value));
 await call('Emulation.setDeviceMetricsOverride',{width:1080,height:340,deviceScaleFactor:1,mobile:false});
 const shot=await call('Page.captureScreenshot',{format:'png'});const bytes=Buffer.from(shot.result.data,'base64');
 await mkdir('docs/diario-ia/qa-resultados/defesa-estacionaria',{recursive:true});await writeFile('docs/diario-ia/qa-resultados/defesa-estacionaria/sequencia.png',bytes);await writeFile('/tmp/legendgirl-defesa-estacionaria.png',bytes);
} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
